/*! @codemaku/arcade offline service worker. Generated by the kit's Vite preset; do not edit. */
/* The build replaces `self.__ARCADE_OFFLINE__` with this site's file list. */

const CFG = self.__ARCADE_OFFLINE__;
const CACHE = `arcade-${CFG.version}`; // this build's files; replaced on every deploy
const RUNTIME = "arcade-runtime"; // fonts and anything fetched later; kept across deploys
const FONT_HOSTS = ["fonts.googleapis.com", "fonts.gstatic.com"];

const scope = self.registration.scope;
const abs = (path) => new URL(path, scope).href;
const noSearch = (url) => {
  const u = new URL(url);
  u.search = "";
  u.hash = "";
  return u.href;
};

// Pixel fonts: cache the stylesheet and every font file it points to, so the
// game looks right offline after one visit. Best effort, never blocks install.
async function cacheStylesheet(cache, href) {
  try {
    const res = await fetch(href, { mode: "cors", credentials: "omit" });
    if (!res.ok) return;
    await cache.put(href, res.clone());
    const css = await res.text();
    const urls = [...css.matchAll(/url\(\s*['"]?([^'")]+)['"]?\s*\)/g)].map((m) =>
      new URL(m[1], href).href,
    );
    await Promise.all(
      urls.map(async (u) => {
        if (await cache.match(u)) return;
        const r = await fetch(u, { mode: "cors", credentials: "omit" });
        if (r.ok) await cache.put(u, r);
      }),
    );
  } catch {
    /* offline or blocked: the runtime handler caches it on the next visit */
  }
}

self.addEventListener("install", (event) => {
  event.waitUntil(
    (async () => {
      const cache = await caches.open(CACHE);
      // cache: "reload" skips the HTTP cache so a deploy never precaches stale files.
      await cache.addAll(CFG.files.map((f) => new Request(abs(f), { cache: "reload" })));
      const runtime = await caches.open(RUNTIME);
      await Promise.all(CFG.stylesheets.map((href) => cacheStylesheet(runtime, href)));
      await Promise.all(
        CFG.urls.map((u) =>
          fetch(u)
            .then((r) => (r.ok || r.type === "opaque") && runtime.put(u, r))
            .catch(() => {}),
        ),
      );
      await self.skipWaiting();
    })(),
  );
});

self.addEventListener("activate", (event) => {
  event.waitUntil(
    (async () => {
      // This worker owns the site's Cache Storage: drop older builds and any
      // cache left by a previous service worker (workbox, hand-written ones).
      const keep = new Set([CACHE, RUNTIME]);
      for (const key of await caches.keys()) if (!keep.has(key)) await caches.delete(key);
      await self.clients.claim();
    })(),
  );
});

async function fromCache(request) {
  return (
    (await caches.match(request, { cacheName: CACHE, ignoreVary: true })) ||
    (await caches.match(request, { cacheName: RUNTIME, ignoreVary: true }))
  );
}

// Pages: network first so a deploy shows up straight away, but give up after
// a few seconds (bad signal at the range) and serve the cached copy instead.
async function page(event) {
  const { request } = event;
  const network = fetch(request).then(async (res) => {
    if (res.ok && res.type === "basic") {
      const cache = await caches.open(CACHE);
      await cache.put(noSearch(request.url), res.clone());
    }
    return res;
  });
  event.waitUntil(network.catch(() => {}));
  const cached = async () => {
    const cache = await caches.open(CACHE);
    return (
      (await cache.match(noSearch(request.url), { ignoreVary: true })) ||
      (await cache.match(abs(CFG.fallback), { ignoreVary: true }))
    );
  };
  const timeout = new Promise((resolve) => setTimeout(resolve, CFG.timeout));
  try {
    const first = await Promise.race([network, timeout]);
    if (first) return first;
    return (await cached()) || (await network);
  } catch {
    return (await cached()) || Response.error();
  }
}

// Fonts and this build's files: cache first, then network (kept for next time).
async function cacheFirst(request) {
  const hit = await fromCache(request);
  if (hit) return hit;
  const res = await fetch(request);
  if (res.ok || res.type === "opaque") {
    const cache = await caches.open(RUNTIME);
    await cache.put(request, res.clone());
  }
  return res;
}

// Anything else on this site (analytics scripts and the like): network first,
// last good copy when offline.
async function networkFirst(request) {
  try {
    const res = await fetch(request);
    if (res.ok && res.type === "basic") {
      const cache = await caches.open(RUNTIME);
      await cache.put(request, res.clone());
    }
    return res;
  } catch (err) {
    const hit = await fromCache(request);
    if (hit) return hit;
    throw err;
  }
}

const precached = new Set(CFG.files.map(abs));

self.addEventListener("fetch", (event) => {
  const { request } = event;
  if (request.method !== "GET" || request.headers.has("range")) return;
  const url = new URL(request.url);
  if (request.mode === "navigate") {
    if (url.origin === location.origin) event.respondWith(page(event));
    return;
  }
  if (url.origin === location.origin) {
    event.respondWith(precached.has(noSearch(url.href)) ? cacheFirst(request) : networkFirst(request));
  } else if (FONT_HOSTS.includes(url.hostname) || CFG.urls.includes(url.href)) {
    event.respondWith(cacheFirst(request));
  }
});
